"use client";

import {
  Sidebar,
  SidebarContent,
  SidebarInset,
  SidebarProvider,
  SidebarRail,
} from "@/components/ui/sidebar";
import type { Meta, StoryObj } from "@storybook/nextjs-vite";
import * as React from "react";

import { InventisAppHeader } from "./app-header/InventisAppHeader";
import { FIGMA_HEADER_FILE_BASE } from "./app-header/figma";

type HeaderArgs = React.ComponentProps<typeof InventisAppHeader>;

const meta = {
  id: "pattern-app-header",
  title: "Pattern/App Header",
  component: InventisAppHeader,
  tags: ["!autodocs"],
  argTypes: {
    variant: {
      name: "variant",
      description:
        "Figma `Type=` — `default` (중앙 비움) · `breadcrumb` · `window` (탭 행).",
      options: ["default", "breadcrumb", "window"],
      control: { type: "radio" },
    },
    globalSearch: {
      name: "globalSearch",
      description: "우측 검색 트리거(⌘K · ⇧ · 도움말 아이콘).",
      control: { type: "boolean" },
    },
    showCreate: {
      name: "showCreate",
      description:
        "우측 Secondary `Create` 버튼. `onCreateClick`으로 `createOpen` 플로우 연결.",
      control: { type: "boolean" },
    },
  },
  args: {
    variant: "default",
    globalSearch: true,
    showCreate: true,
  },
  parameters: {
    layout: "fullscreen",
    docs: {
      description: {
        component: `Inventis DS 앱 상단 헤더 (Figma ❖ Header). \`SidebarTrigger\` 는 \`SidebarProvider\` 하위에서 동작합니다. ([Figma 파일](${FIGMA_HEADER_FILE_BASE}))`,
      },
    },
  },
} satisfies Meta<typeof InventisAppHeader>;

export default meta;

type Story = StoryObj<typeof meta>;

function HeaderPreviewShell(props: HeaderArgs) {
  return (
    <SidebarProvider defaultOpen>
      <Sidebar collapsible="icon">
        <SidebarContent className="gap-0 p-2">
          <p className="text-sidebar-foreground/70 px-2 py-3 text-xs">
            Preview sidebar · 트리거로 접기
          </p>
        </SidebarContent>
        <SidebarRail />
      </Sidebar>
      <SidebarInset className="min-h-svh overflow-hidden" dir="ltr">
        <InventisAppHeader {...props} />
        <div className="text-muted-foreground flex flex-1 flex-col gap-2 p-4 text-sm">
          <p>메인 콘텐츠 영역</p>
          <p className="text-xs">
            Cmd/Ctrl+B · 헤더 왼쪽 트리거로 사이드바 토글
          </p>
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

/** Figma Type=Default — 트리거 · 구분선 · 빈 중앙 · 검색 · Create */
export const Default: Story = {
  args: { variant: "default" },
  render: (args) => <HeaderPreviewShell {...args} />,
};

/** Figma Type=Breadcrumb — Home → RO List → RO Detail */
export const Breadcrumb: Story = {
  args: { variant: "breadcrumb" },
  render: (args) => <HeaderPreviewShell {...args} />,
};

/** Figma Type=Window — 탭 · 더보기 · New Window */
export const Window: Story = {
  args: { variant: "window" },
  render: (args) => <HeaderPreviewShell {...args} />,
};

"use client";

import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";
import { Button } from "@/components/ui/button";
import { Kbd } from "@/components/ui/kbd";
import { Separator } from "@/components/ui/separator";
import { SidebarTrigger } from "@/components/ui/sidebar";
import { cn } from "@/bases/radix/lib/utils";
import { CircleHelp, MoreHorizontal, Plus, Search, X } from "lucide-react";
import * as React from "react";

import {
  defaultInventisHeaderBreadcrumbs,
  defaultInventisHeaderWindowTabs,
  type InventisHeaderBreadcrumbItem,
  type InventisHeaderWindowTab,
} from "./app-header.config";

export type InventisAppHeaderVariant = "default" | "breadcrumb" | "window";

export type InventisAppHeaderProps = {
  /** Figma `Type=` — 레이아웃 축 */
  variant?: InventisAppHeaderVariant;
  /** 글로벌 검색 UI (⌘K · ⇧ · 도움말 아이콘) */
  globalSearch?: boolean;
  /** 우측 Secondary Create 버튼 */
  showCreate?: boolean;
  breadcrumbs?: InventisHeaderBreadcrumbItem[];
  windowTabs?: InventisHeaderWindowTab[];
  className?: string;
  onSearchClick?: () => void;
  /** Figma `createOpen` — Create 관련 오버레이/플로우 열기 */
  onCreateClick?: () => void;
  onNewWindowClick?: () => void;
  onTabClose?: (tabId: string) => void;
  onTabMenuClick?: (tabId: string) => void;
};

function InventisHeaderSearchTrigger({
  className,
  onClick,
}: {
  className?: string;
  onClick?: () => void;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "border-input bg-background dark:bg-input/30 text-muted-foreground inline-flex h-8 w-full max-w-80 min-w-[200px] shrink-0 items-center gap-1.5 rounded-lg border px-2.5 py-1 text-left text-sm shadow-xs transition-colors",
        "hover:bg-muted/40 focus-visible:ring-ring focus-visible:ring-[3px] focus-visible:outline-none",
        className,
      )}
    >
      <Search className="size-4 shrink-0" aria-hidden />
      <span className="min-w-0 flex-1 truncate">Search</span>
      <span className="text-muted-foreground flex shrink-0 items-center gap-1">
        <Kbd className="pointer-events-none">⌘K</Kbd>
        <Kbd className="pointer-events-none">⇧</Kbd>
      </span>
      <CircleHelp className="size-4 shrink-0 opacity-80" aria-hidden />
    </button>
  );
}

function InventisHeaderWindowTabButton({
  tab,
  onClose,
  onEllipsisClick,
}: {
  tab: InventisHeaderWindowTab;
  onClose?: (id: string) => void;
  onEllipsisClick?: (id: string) => void;
}) {
  if (tab.state === "ellipsis") {
    return (
      <Button
        type="button"
        variant="ghost"
        size="icon-sm"
        className="size-9 shrink-0 rounded-md"
        aria-label="More tabs"
        onClick={() => onEllipsisClick?.(tab.id)}
      >
        <MoreHorizontal className="size-4" />
      </Button>
    );
  }

  const selected = tab.state === "selected";

  return (
    <div
      className={cn(
        "flex h-9 max-w-[100px] shrink-0 items-center gap-0.5 rounded-md px-1 font-medium",
        selected && "bg-accent text-accent-foreground",
        !selected && "text-muted-foreground",
      )}
    >
      <button
        type="button"
        className={cn(
          "hover:bg-muted/50 flex min-w-0 flex-1 items-center rounded-sm px-1.5 py-1 text-sm",
          selected && "hover:bg-accent/80",
        )}
      >
        <span className="truncate">{tab.label}</span>
      </button>
      <button
        type="button"
        className={cn(
          "text-muted-foreground hover:text-foreground flex size-7 shrink-0 items-center justify-center rounded-sm",
          selected && "hover:bg-accent/80",
        )}
        aria-label={`Close ${tab.label}`}
        onClick={() => onClose?.(tab.id)}
      >
        <X className="size-4 opacity-70" aria-hidden />
      </button>
    </div>
  );
}

/**
 * Inventis DS 앱 상단 헤더 (Figma ❖ Header — Default / Breadcrumb / Window).
 * `SidebarTrigger` 사용 시 상위에 `SidebarProvider`가 있어야 합니다.
 */
export function InventisAppHeader({
  variant = "default",
  globalSearch = true,
  showCreate = true,
  breadcrumbs = defaultInventisHeaderBreadcrumbs,
  windowTabs = defaultInventisHeaderWindowTabs,
  className,
  onSearchClick,
  onCreateClick,
  onNewWindowClick,
  onTabClose,
  onTabMenuClick,
}: InventisAppHeaderProps) {
  return (
    <header
      className={cn(
        "bg-background flex h-[49px] w-full shrink-0 items-center gap-4 border-b px-6",
        className,
      )}
    >
      <div className="flex min-w-0 shrink-0 items-center gap-2">
        <SidebarTrigger className="size-7 rounded-md" />
        <Separator orientation="vertical" className="h-[15px] w-px" />

        {variant === "default" ? null : variant === "breadcrumb" ? (
          <Breadcrumb>
            <BreadcrumbList className="gap-2.5 sm:gap-2.5">
              {breadcrumbs.flatMap((item, i) => {
                const nodes: React.ReactNode[] = [];
                if (i > 0) {
                  nodes.push(
                    <BreadcrumbSeparator
                      key={`sep-${i}`}
                      className="[&>svg]:size-3.5"
                    />,
                  );
                }
                nodes.push(
                  <BreadcrumbItem key={`${item.label}-${i}`}>
                    {item.href ? (
                      <BreadcrumbLink
                        href={item.href}
                        className="text-muted-foreground"
                      >
                        {item.label}
                      </BreadcrumbLink>
                    ) : (
                      <BreadcrumbPage>{item.label}</BreadcrumbPage>
                    )}
                  </BreadcrumbItem>,
                );
                return nodes;
              })}
            </BreadcrumbList>
          </Breadcrumb>
        ) : (
          <nav
            className="flex min-w-0 items-center gap-1"
            aria-label="Window tabs"
          >
            {windowTabs.map((tab) => (
              <InventisHeaderWindowTabButton
                key={tab.id}
                tab={tab}
                onClose={onTabClose}
                onEllipsisClick={onTabMenuClick}
              />
            ))}
            <Button
              type="button"
              variant="ghost"
              size="sm"
              className="h-8 gap-1.5 px-2.5 font-medium"
              onClick={onNewWindowClick}
            >
              <Plus className="size-4" />
              New Window
            </Button>
          </nav>
        )}
      </div>

      <div className="flex min-w-0 flex-1 items-center justify-end gap-2">
        {globalSearch ? (
          <InventisHeaderSearchTrigger onClick={onSearchClick} />
        ) : null}
        {showCreate ? (
          <Button
            type="button"
            variant="secondary"
            size="sm"
            className="h-8 gap-1.5 px-2.5"
            onClick={onCreateClick}
          >
            <Plus className="size-4" />
            Create
          </Button>
        ) : null}
      </div>
    </header>
  );
}

export type InventisHeaderBreadcrumbItem = {
  label: string;
  /** 없으면 현재 페이지(비링크) */
  href?: string;
};

export type InventisHeaderWindowTabState =
  | "selected"
  | "unselected"
  | "ellipsis";

export type InventisHeaderWindowTab = {
  id: string;
  label: string;
  state: InventisHeaderWindowTabState;
};

/** Figma Breadcrumb 행 기본 샘플 */
export const defaultInventisHeaderBreadcrumbs: InventisHeaderBreadcrumbItem[] =
  [
    { label: "Home", href: "#" },
    { label: "RO List", href: "#" },
    { label: "RO Detail" },
  ];

/** Figma Window 행 기본 샘플 */
export const defaultInventisHeaderWindowTabs: InventisHeaderWindowTab[] = [
  { id: "t1", label: "Appointment", state: "selected" },
  { id: "t2", label: "", state: "ellipsis" },
  { id: "t3", label: "OPPT-2024-032", state: "unselected" },
];

/**
 * Inventis DS App Header — Figma 참조.
 * Variants 섹션: node 26762:314488 (❖ Header 3종)
 */

export const FIGMA_HEADER_FILE_KEY = "MvGuEwW5KUn5VcpSEWm2ve";

export const FIGMA_HEADER_FILE_BASE = `https://www.figma.com/design/${FIGMA_HEADER_FILE_KEY}/260303_Inventis-DS--Shadcn-ui`;

/** Variants 프레임 (Default / Breadcrumb / Window 행) */
export const FIGMA_HEADER_VARIANTS_SECTION = "26762:314488";

/** 심볼: Type=Default */
export const FIGMA_HEADER_TYPE_DEFAULT = "26762:322989";

/** 심볼: Type=Breadcrumb */
export const FIGMA_HEADER_TYPE_BREADCRUMB = "26762:322988";

/** 심볼: Type=Window */
export const FIGMA_HEADER_TYPE_WINDOW = "26762:322990";

/** Window Tab 프로퍼티 섹션 */
export const FIGMA_HEADER_WINDOW_TAB_PROPERTIES = "26762:314715";

/** NavItem 스펙 카드 (독스 참고용) */
export const FIGMA_HEADER_NAV_ITEM_SPEC = "26762:315157";

/**
 * 독스/스펙 라벨에 해당하는 노드-id (Figma Pages 트리와 동일).
 * 구현 검증·피그마 동기화 시 참고.
 */
export const FIGMA_HEADER_DOC_NODE_IDS = [
  "26762:314688", // Example
  "26762:314690", // Default
  "26762:314691", // Breadcrumb
  "26762:314692", // createOpen
  "26762:314695", // Window
  "26762:327698",
  "26762:315157", // NavItem spec
  "26762:314488", // Variants
  "26762:314696",
  "26762:327996",
  "26762:314715", // Properties / Window Tab
  "26762:328294",
  "26762:327391",
] as const;

export function figmaHeaderNodeUrl(nodeId: string): string {
  return `${FIGMA_HEADER_FILE_BASE}?node-id=${encodeURIComponent(nodeId.replace(":", "-"))}&m=dev`;
}

import * as React from "react";

const tableStyle: React.CSSProperties = {
  width: "100%",
  borderCollapse: "collapse",
  fontSize: "13px",
  margin: "16px 0",
};

export function AppHeaderCodeStructureTable() {
  const rows = [
    {
      file: "app-header/InventisAppHeader.tsx",
      role: "헤더 UI (`variant` · 검색 · Create · breadcrumb/window)",
    },
    {
      file: "app-header/app-header.config.ts",
      role: "기본 breadcrumb·window 탭 샘플 데이터",
    },
    {
      file: "app-header/figma.ts",
      role: "Figma node-id · Variants 섹션 · 독스 노드 목록",
    },
  ];
  return (
    <table style={tableStyle}>
      <thead>
        <tr style={{ borderBottom: "1px solid var(--border)" }}>
          <th style={{ textAlign: "left", padding: "8px 12px", width: "42%" }}>
            파일
          </th>
          <th style={{ textAlign: "left", padding: "8px 12px" }}>역할</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((r) => (
          <tr key={r.file} style={{ borderBottom: "1px solid var(--border)" }}>
            <td style={{ padding: "8px 12px", verticalAlign: "top" }}>
              <code style={{ fontSize: "12px" }}>{r.file}</code>
            </td>
            <td
              style={{
                padding: "8px 12px",
                color: "var(--muted-foreground)",
                verticalAlign: "top",
              }}
            >
              {r.role}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

export function AppHeaderVariantsTable() {
  const rows = [
    { story: "Default", desc: "Type=Default — 중앙 비움" },
    { story: "Breadcrumb", desc: "Type=Breadcrumb — 경로" },
    { story: "Window", desc: "Type=Window — 멀티 윈도우 탭" },
  ];
  return (
    <table style={tableStyle}>
      <thead>
        <tr style={{ borderBottom: "1px solid var(--border)" }}>
          <th style={{ textAlign: "left", padding: "8px 12px", width: "28%" }}>
            스토리
          </th>
          <th style={{ textAlign: "left", padding: "8px 12px" }}>설명</th>
        </tr>
      </thead>
      <tbody>
        {rows.map((r) => (
          <tr key={r.story} style={{ borderBottom: "1px solid var(--border)" }}>
            <td style={{ padding: "8px 12px" }}>
              <strong>{r.story}</strong>
            </td>
            <td
              style={{
                padding: "8px 12px",
                color: "var(--muted-foreground)",
              }}
            >
              {r.desc}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
